// Literal port of the team's Casa3DSDK (module house/baseboard). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installHouseBaseboard(K: Kernel, shared: Shared): void {
  const { Y0, bx, cursor, sideOf } = K;
  const sh = (...a: any[]): any => K.sh(...a);
  // ===== R46: external baseboard and protective sidewalk around the ground floor, closing the outer corners =====
  function baseboardAndSidewalk() {
    const R = shared.ctx.r, W = 0.6, t = 0.012, ht = 0.35, color = sh(shared.ctx.colors.facade != null ? shared.ctx.colors.facade : 0xd8d0c0, 0.62), y0 = Y0(0), cal = 0xd4d0c6;
    const ws = R.walls.filter(w => w.floor === 0 && w.type === 'wall').map(w => { const au = w.axis === 'u'; return { w, au, L: au ? w.v0 : w.u0, a: Math.min(au ? w.u0 : w.v0, au ? w.u1 : w.v1), b: Math.max(au ? w.u0 : w.v0, au ? w.u1 : w.v1), th: w.thickness || 0.15 }; });
    cursor.group = 'f0';
    // what meets the end of a wall (point e = position along the axis, L = line): +1 convex (another wall moves away on the outside), -1 concave or in a T, 0 free end
    const junction = (A, e, sd) => {
      let r = 0;
      for (const B of ws) { if (B === A || B.au === A.au) continue; if (Math.abs(B.L - e) > 0.03 || A.L < B.a - 0.03 || A.L > B.b + 0.03) continue;
        const dir = Math.abs(B.a - A.L) < 0.03 ? 1 : Math.abs(B.b - A.L) < 0.03 ? -1 : 0; // direction in which B leaves the line of A
        if (dir === 0 || dir === sd) return -1; r = 1; }
      return r;
    };
    for (const A of ws) for (const [side, sd] of [[A.w.sides[0], -1], [A.w.sides[1], 1]]) {
      if (!sideOf(side, false).exterior) continue;
      const strip = (k, y1, y2, o0, o1, mat, c, y1b?) => { // k = extra clearance at convex corners; o0..o1 = offset from the outer face
        const ea = junction(A, A.a, sd) > 0 ? A.th / 2 + k : junction(A, A.a, sd) < 0 ? -A.th / 2 : 0, eb = junction(A, A.b, sd) > 0 ? A.th / 2 + k : junction(A, A.b, sd) < 0 ? -A.th / 2 : 0;
        const s0 = A.a - ea, s1 = A.b + eb, f0 = A.L + sd * (A.th / 2 + o0), f1 = A.L + sd * (A.th / 2 + o1), lo = Math.min(f0, f1), hi = Math.max(f0, f1);
        if (s1 - s0 < 1e-3) return; if (A.au) bx(mat, s0, y1, lo, s1, y2, hi, c); else bx(mat, lo, y1, s0, hi, y2, s1, c);
      };
      strip(t, y0, y0 + ht, 0, t, 'plaster', color);          // baseboard (35 cm dark strip) with closed corners
      strip(W, y0, y0 + 0.045, 0, W, 'sidewalk', cal);      // 60 cm protective sidewalk with filled corners
    }
  }
  Object.assign(K, { baseboardAndSidewalk });
}
